import React, { useState, useEffect } from 'react';
import { useContexState } from '../hooks/context';

import api from '../services/api'

interface ConvertListParam {
    data: {
        id: number;
        number: number;
        name: string;
        phone: string;
        price: number;
    }[]
};

interface ConvertListReturn {
    [key: string]: [{
        id: number;
        name: string;
        phone: string;
        price: number;
    }]
};

interface Lines {
    firstCard: number;
    id: string;
};

export function useLoadPage() {
    const [getList, setGetList] = useState<ConvertListReturn>();
    const { listData, setlistData, perPage } = useContexState();

    function convertList({ data }: ConvertListParam) {
        return data.reduce((h: ConvertListReturn, card) => {
            const user = {
                id: card.id,
                name: card.name,
                phone: card.phone,
                price: card.price,
            };
            return Object.assign(h, {
                [card.number]: (h[card.number] || []).concat(user)
            });
        }, {});
    };

    function limiterNumber(number: number) {
        if (number + (perPage * 6) - 1 < 9999) {
            return number + (perPage * 6) - 1
        } else {
            return 9999
        }
    };

    /*
    async function fetchApi() {
        const number = listData[0]?.firstCard;
        return await api.get("getCards", {
            params: {
                firstNumber: number,
                lastNumber: limiterNumber(number),
            }
        }
        ).then((responce) => {
            console.log(JSON.stringify(responce.data));
            setGetList(convertList(responce));
        });
    };
*/
    const number = listData[0]?.firstCard;

    let qq = 0

    useEffect(() => {
        if (number !== undefined && qq === 0) {
            console.log('123123');
            (async function () {
                return await api.get("getCards", {
                    params: {
                        firstNumber: number,
                        lastNumber: limiterNumber(number),
                    }
                }
                ).then((responce) => {
                    console.log(JSON.stringify(responce.data));
                    setGetList(convertList(responce));
                });
            })();
        }
        return () => { qq = 1 }
    }, [listData]);

    function LoadPage(value: number | number = 0) {
        const lines: Lines[] = [];
        for (let i = 0; i < perPage; i++) {
            lines.push({
                firstCard: (i * 6) + value, id: String(i)
            });
        };
        setlistData([...lines]);
    };

    return { LoadPage, getList };
};
